    private void UpdateSet()
    {
        if(sets.SelectedItem is not ContentChoice selected)return;setEquipment.Bind(setPieces.Select(p=>new EquipmentViewItem(p,p.Item,Active:p.Selected)),catalog.Tooltips,lookup,previewLevel);var set=catalog.Tooltips.Sets[selected.Id];var chosen=setPieces.Where(p=>p.Selected).Select(p=>p.Item).ToList();setTotals.ItemsSource=GearDesign.PieceTotals(chosen,catalog.Tooltips,previewLevel);int count=chosen.Count;changing=true;pieceCount.SelectedIndex=count;changing=false;var missing=set.Members.Where(i=>!lookup.ContainsKey(i)).ToList();var conflicts=chosen.SelectMany(i=>GearDesign.Targets(i).Length==1?new[]{GearDesign.Targets(i)[0]}:Array.Empty<int>()).GroupBy(i=>i).Where(g=>g.Count()>1).Select(g=>GearDesign.EquipmentSlots[g.Key]).ToList();if(chosen.Count(i=>i.Slot==11)>2)conflicts.Add("more than two rings");if(chosen.Count(i=>i.Slot==12)>2)conflicts.Add("more than two trinkets");
